+import path from "node:path";
+import type { Request, Response } from "express";
+import { Router } from "express";
+
+const router = Router();
+const EXPORT_ROOT = "/srv/app/exports";
+const EXPORT_ID = /^[a-f0-9]{32}$/;
+
+router.get("/exports/:id", async (req: Request, res: Response) => {
+  const exportId = req.params.id;
+  if (!EXPORT_ID.test(exportId)) {
+    return res.status(400).json({ error: "invalid export id" });
+  }
+  const target = path.join(EXPORT_ROOT, `${exportId}.csv`);
+  res.setHeader("Cache-Control", "private");
+  return res.sendFile(target);
+});
+
+export default router;

