+import type { Request, Response } from "express";
+import { Router } from "express";
+import { isPublicHostname } from "../security/network";
+
+const router = Router();
+
+router.post("/webhooks/test", async (req: Request, res: Response) => {
+  const target = new URL(String(req.body.url));
+  if (target.protocol !== "https:") {
+    return res.status(400).json({ error: "https required" });
+  }
+  if (!(await isPublicHostname(target.hostname))) {
+    return res.status(400).json({ error: "public host required" });
+  }
+
+  const upstream = await fetch(target);
+  const body = await upstream.text();
+  return res.json({ status: upstream.status, body });
+});
+
+export default router;

