+import type { Request, Response } from "express";
+import { Router } from "express";
+
+const router = Router();
+const ALLOWED_HOSTS = new Set(["hooks.partner.example.invalid"]);
+
+router.post("/webhooks/test", async (req: Request, res: Response) => {
+  const target = new URL(String(req.body.url));
+  if (target.protocol !== "https:" || !ALLOWED_HOSTS.has(target.hostname)) {
+    return res.status(400).json({ error: "destination not allowed" });
+  }
+  if (target.username || target.password || target.port) {
+    return res.status(400).json({ error: "invalid destination" });
+  }
+
+  const upstream = await fetch(target, {
+    redirect: "manual",
+    signal: AbortSignal.timeout(3000),
+  });
+  return res.json({ status: upstream.status });
+});
+
+export default router;

